def mention(note):
    if note >= 16:
        return "Très bien"
    if note >= 10:
        return "Admis"
    return "Ajourné"


def test_mention():
    assert mention(18) == "Très bien"
    assert mention(13) == "Admis"
    assert mention(5) == "Ajourné"


# Vérification fournie : ne la modifie pas.
MUTANTS = [
    lambda n: "Très bien" if n > 16 else ("Admis" if n >= 10 else "Ajourné"),
    lambda n: "Très bien" if n >= 16 else ("Admis" if n > 10 else "Ajourné"),
    lambda n: "Admis" if n >= 10 else "Ajourné",
]


def evaluer_tests():
    global mention
    original = mention
    test_mention()
    resultats = []
    for mutant in MUTANTS:
        mention = mutant
        try:
            test_mention()
            resultats.append("raté")
        except Exception:
            resultats.append("détecté")
    mention = original
    return resultats

